begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) values
 ('29111111-1111-4111-8111-111111111111','package-owner@example.invalid',now(),'{}','{}'),
 ('29222222-2222-4222-8222-222222222222','package-operator@example.invalid',now(),'{}','{}');
insert into public.tenants(id,name) values('29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Studio sintetico pacchetti');
insert into public.users(id,tenant_id,display_name,role,clinical_access) values
 ('29111111-1111-4111-8111-111111111111','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Owner sintetico','owner',true),
 ('29222222-2222-4222-8222-222222222222','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Operator sintetico','operator',true);
insert into public.clients(id,tenant_id,first_name,last_name) values('29000000-0000-4000-8000-000000000011','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Cliente','Sintetica');
insert into public.services(id,tenant_id,name,duration_minutes) values('29000000-0000-4000-8000-000000000012','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Servizio sintetico',60);
insert into public.locations(id,tenant_id,name) values('29000000-0000-4000-8000-000000000013','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Sede sintetica');
insert into public.appointments(id,tenant_id,client_id,service_id,operator_id,location_id,service_name,price_cents,starts_at,ends_at) values
 ('29000000-0000-4000-8000-000000000014','29aaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','29000000-0000-4000-8000-000000000011','29000000-0000-4000-8000-000000000012','29111111-1111-4111-8111-111111111111','29000000-0000-4000-8000-000000000013','Servizio sintetico',0,now()+interval '2 days',now()+interval '2 days 1 hour');
create temp table package_results(key text primary key,value jsonb);
grant all on package_results to authenticated,service_role;
insert into package_results values('content',$json${"title": "Modello sintetico SQL", "source_date": "2026-08-09", "source_scope": "Testo sintetico per prova database.", "description": "Testo sintetico per prova database.", "treatment_statement": "Testo sintetico per prova database.", "introduction": "Testo sintetico per prova database.", "aftercare": "Testo sintetico per prova database.", "aftercare_statement": "Testo sintetico per prova database.", "health_statement": "Testo sintetico per prova database.", "photo_notice": "Testo sintetico per prova database.", "photo_documentation": "Testo sintetico per prova database.", "photo_demonstration": "Testo sintetico per prova database.", "guardian_statement": "Testo sintetico per prova database.", "key": "microblading", "revision": 1, "questions": [{"id": "29000000-0000-4000-8000-000000000001", "label": "Domanda sintetica SQL?", "type": "yes_no", "required": true}], "privacy_notice": "Informativa esclusivamente sintetica per test di isolamento e consenso, non valida per trattamenti.", "jurisdiction": "Ambito sintetico", "minors_enabled": false, "minimum_age": null, "representatives_required": null, "minors_basis": "", "reviewed": false}$json$);
select ok((select relrowsecurity from pg_class where oid='app_private.document_profiles'::regclass),'document_profiles has RLS');
select ok(not has_table_privilege('anon','app_private.document_profiles','SELECT'),'anon cannot directly read document_profiles');
select ok(not has_table_privilege('authenticated','app_private.document_profiles','SELECT'),'authenticated cannot directly read document_profiles');
select ok(not has_table_privilege('service_role','app_private.document_profiles','SELECT'),'service_role cannot directly read document_profiles');
select ok((select relrowsecurity from pg_class where oid='app_private.consent_packages'::regclass),'consent_packages has RLS');
select ok(not has_table_privilege('anon','app_private.consent_packages','SELECT'),'anon cannot directly read consent_packages');
select ok(not has_table_privilege('authenticated','app_private.consent_packages','SELECT'),'authenticated cannot directly read consent_packages');
select ok(not has_table_privilege('service_role','app_private.consent_packages','SELECT'),'service_role cannot directly read consent_packages');
select ok((select relrowsecurity from pg_class where oid='app_private.consent_package_versions'::regclass),'consent_package_versions has RLS');
select ok(not has_table_privilege('anon','app_private.consent_package_versions','SELECT'),'anon cannot directly read consent_package_versions');
select ok(not has_table_privilege('authenticated','app_private.consent_package_versions','SELECT'),'authenticated cannot directly read consent_package_versions');
select ok(not has_table_privilege('service_role','app_private.consent_package_versions','SELECT'),'service_role cannot directly read consent_package_versions');
select ok((select relrowsecurity from pg_class where oid='app_private.consent_packets'::regclass),'consent_packets has RLS');
select ok(not has_table_privilege('anon','app_private.consent_packets','SELECT'),'anon cannot directly read consent_packets');
select ok(not has_table_privilege('authenticated','app_private.consent_packets','SELECT'),'authenticated cannot directly read consent_packets');
select ok(not has_table_privilege('service_role','app_private.consent_packets','SELECT'),'service_role cannot directly read consent_packets');
select ok((select relrowsecurity from pg_class where oid='app_private.consent_packet_parties'::regclass),'consent_packet_parties has RLS');
select ok(not has_table_privilege('anon','app_private.consent_packet_parties','SELECT'),'anon cannot directly read consent_packet_parties');
select ok(not has_table_privilege('authenticated','app_private.consent_packet_parties','SELECT'),'authenticated cannot directly read consent_packet_parties');
select ok(not has_table_privilege('service_role','app_private.consent_packet_parties','SELECT'),'service_role cannot directly read consent_packet_parties');
select ok((select relrowsecurity from pg_class where oid='app_private.consent_packet_countersignatures'::regclass),'consent_packet_countersignatures has RLS');
select ok(not has_table_privilege('anon','app_private.consent_packet_countersignatures','SELECT'),'anon cannot directly read consent_packet_countersignatures');
select ok(not has_table_privilege('authenticated','app_private.consent_packet_countersignatures','SELECT'),'authenticated cannot directly read consent_packet_countersignatures');
select ok(not has_table_privilege('service_role','app_private.consent_packet_countersignatures','SELECT'),'service_role cannot directly read consent_packet_countersignatures');
select ok(not has_function_privilege('authenticated','public.use_consent_packet(text,text,jsonb)','EXECUTE'),'capability gateway not ordinary RPC');
select ok(has_function_privilege('service_role','public.use_consent_packet(text,text,jsonb)','EXECUTE'),'gateway only service role');
select ok(not has_function_privilege('authenticated','public.save_treatment_preparation_before_packages(uuid,uuid,integer,integer,uuid,uuid,jsonb,uuid[])','EXECUTE'),'no bypass via renamed preparation');
select ok(not has_function_privilege('authenticated','public.publish_clinical_template_before_packages(uuid,uuid,integer,text,text,text,jsonb,uuid)','EXECUTE'),'no bypass via renamed publisher');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"29222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select throws_ok($$select public.consent_package_catalog()$$,'42501',null,'operator cannot manage library');
select set_config('request.jwt.claims','{"sub":"29111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select lives_ok($$select public.save_document_profile(0,'{"legal_name":"Studio sintetico","tax_id":"TEST000","data_controller":"Titolare sintetico","address":"Via sintetica 1","email":"studio@example.invalid","phone":"000000000","pec":""}')$$,'owner configures professional profile');
select throws_ok($$select public.save_document_profile(0,'{"legal_name":"Studio sintetico","tax_id":"TEST000","data_controller":"Titolare sintetico","address":"Via sintetica 1","email":"studio@example.invalid","phone":"000000000","pec":""}')$$,'40001',null,'profile stale version denied');
insert into package_results values('draft',public.save_consent_package(null,0,'29000000-0000-4000-8000-000000000012',(select value from package_results where key='content')));
select throws_ok($$select public.publish_consent_package((select (value->>'id')::uuid from package_results where key='draft'),1)$$,'22023','PACKAGE_REVIEW_REQUIRED','unreviewed draft cannot publish');
select is(public.inspect_deletion('services','29000000-0000-4000-8000-000000000012')->>'allowed','false','draft package protects its service');
update package_results set value=value||'{"reviewed":true}'::jsonb where key='content';
insert into package_results values('updated',public.save_consent_package((select (value->>'id')::uuid from package_results where key='draft'),1,'29000000-0000-4000-8000-000000000012',(select value from package_results where key='content')));
insert into package_results values('published',public.publish_consent_package((select (value->>'id')::uuid from package_results where key='draft'),2));
select is(jsonb_array_length(public.available_consent_packages('29000000-0000-4000-8000-000000000014')),1,'one published service package');
insert into package_results values('issued',public.prepare_consent_packet(gen_random_uuid(),'29000000-0000-4000-8000-000000000014',1,(select (value->>'published_version_id')::uuid from package_results where key='published'),'{"date_of_birth":"1990-01-01","birthplace":"Luogo sintetico","session_kind":"first","identity_verified":true,"verification_method":"Verifica sintetica in presenza","representatives":[]}','{}','link'));
set local role service_role;
select is(public.use_consent_packet(encode(digest((select value->'links'->0->>'token' from package_results where key='issued'),'sha256'),'hex'),'answers','{"answers":{"29000000-0000-4000-8000-000000000001":false}}')->>'ok','false','no clinical collection before consent');
reset role;
create function pg_temp.reject_packet_audit() returns trigger language plpgsql as $$begin if new.action='packet.health' then raise exception 'TEST_AUDIT_FAILURE' using errcode='P0001';end if;return new;end;$$;
create trigger test_packet_audit_failure before insert on public.audit_log for each row execute function pg_temp.reject_packet_audit();
set local role service_role;
select throws_ok($$select public.use_consent_packet(encode(digest((select value->'links'->0->>'token' from package_results where key='issued'),'sha256'),'hex'),'health','{"allowed":true}')$$,'P0001','TEST_AUDIT_FAILURE','audit failure rolls back health receipt');
reset role;
select is((select count(*)::int from app_private.consent_packet_parties where packet_id=(select (value->>'id')::uuid from package_results where key='issued') and health is not null),0,'no unaudited health choice persisted');
drop trigger test_packet_audit_failure on public.audit_log;
set local role service_role;
select is(public.use_consent_packet(encode(digest((select value->'links'->0->>'token' from package_results where key='issued'),'sha256'),'hex'),'health','{"allowed":false}')->'context'->>'stage','declined','health refusal recorded');
select is(public.use_consent_packet(encode(digest((select value->'links'->0->>'token' from package_results where key='issued'),'sha256'),'hex'),'health','{"allowed":true}')->>'ok','false','refusal cannot be changed by a retry');
reset role;
select is((select answers from app_private.preparation_answers where preparation_id=(select preparation_id from public.consent_requests where id=(select (value->>'id')::uuid from package_results where key='issued'))),'{}'::jsonb,'refusal leaves health answers empty');
select throws_ok($$update app_private.consent_packet_parties set health='{"allowed":true}' where packet_id=(select (value->>'id')::uuid from package_results where key='issued')$$,'23514','IMMUTABLE_DOCUMENT','health evidence immutable even to privileged update');
select throws_ok($$delete from app_private.consent_package_versions$$,'23514','IMMUTABLE_DOCUMENT','published content immutable');
select is((select status from public.appointments where id='29000000-0000-4000-8000-000000000014'),'booked','refusal preserves ordinary booking');
select * from finish();
rollback;
